   973  static int parse_input(h2o_http2_conn_t *conn)
   974  {
   975      /* handle the input */
   976      while (conn->state < H2O_HTTP2_CONN_STATE_IS_CLOSING && conn->sock->input->size != 0) {
   977          /* process a frame */
   978          const char *err_desc = NULL;
   979          ssize_t ret = conn->_read_expect(conn, (uint8_t *)conn->sock->input->bytes, conn->sock->input->size, &err_desc);
   980          if (ret == H2O_HTTP2_ERROR_INCOMPLETE) {
   981              break;
   982          } else if (ret < 0) {
   983              if (ret != H2O_HTTP2_ERROR_PROTOCOL_CLOSE_IMMEDIATELY) {
   984                  enqueue_goaway(conn, (int)ret,
   985                                 err_desc != NULL ? (h2o_iovec_t){(char *)err_desc, strlen(err_desc)} : (h2o_iovec_t){NULL});
   986              }
   987              return close_connection(conn);
   988          }
   989          /* advance to the next frame */
   990          h2o_buffer_consume(&conn->sock->input, ret);
   991      }
   992      return 0;
   993  }
